import type { SupabaseClient } from '@supabase/supabase-js';

/**
 * Pickup slots for today, generated by the `list_pickup_slots` SQL function from the shop's
 * hours and capacity. Choosing a slot is optional: without one the order is prepared right away.
 */

export interface PickupSlotOption {
  /** ISO timestamp sent to `place-order` as `pickupTime`. */
  start: string;
  taken: number;
  capacity: number;
  full: boolean;
}

interface SlotRow {
  slot_start: string;
  taken: number;
  capacity: number;
  is_full: boolean;
}

export function slotsFromRows(rows: readonly SlotRow[] | null | undefined): PickupSlotOption[] {
  return (rows ?? []).map((r) => ({ start: r.slot_start, taken: r.taken, capacity: r.capacity, full: r.is_full }));
}

/** Throws when the slots cannot be loaded, so the screen can show an error and still allow "as soon as possible". */
export async function listPickupSlots(client: Pick<SupabaseClient, 'rpc'>, shopId: string): Promise<PickupSlotOption[]> {
  const { data, error } = await client.rpc('list_pickup_slots', { p_shop_id: shopId });
  if (error) throw new Error('No pudimos cargar los horarios de recogida.');
  return slotsFromRows(data as SlotRow[] | null);
}

/** Clock label such as `9:20 a. m.` in the device's time zone. */
export function slotClockLabel(startIso: string): string {
  const d = new Date(startIso);
  const h = d.getHours();
  const m = String(d.getMinutes()).padStart(2, '0');
  return `${h % 12 === 0 ? 12 : h % 12}:${m} ${h < 12 ? 'a. m.' : 'p. m.'}`;
}
